"""Recommendation score model."""

from datetime import datetime, timezone

from sqlalchemy import (
    DateTime,
    Float,
    ForeignKey,
    Integer,
    JSON,
    String,
    UniqueConstraint,
)
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.core.database import Base


def utc_now() -> datetime:
    return datetime.now(timezone.utc)


class Recommendation(Base):
    """Deterministic recommendation result generated by Python."""

    __tablename__ = "recommendations"

    __table_args__ = (
        UniqueConstraint(
            "session_id",
            "product_id",
            name="uq_recommendation_session_product",
        ),
    )

    id: Mapped[int] = mapped_column(
        Integer,
        primary_key=True,
        autoincrement=True,
    )

    session_id: Mapped[str] = mapped_column(
        String(36),
        ForeignKey(
            "search_sessions.id",
            ondelete="CASCADE",
        ),
        nullable=False,
        index=True,
    )

    product_id: Mapped[int] = mapped_column(
        Integer,
        ForeignKey(
            "products.id",
            ondelete="CASCADE",
        ),
        nullable=False,
        index=True,
    )

    final_score: Mapped[float] = mapped_column(
        Float,
        nullable=False,
    )

    budget_score: Mapped[float] = mapped_column(
        Float,
        nullable=False,
        default=0.0,
    )

    requirement_score: Mapped[float] = mapped_column(
        Float,
        nullable=False,
        default=0.0,
    )

    purpose_score: Mapped[float] = mapped_column(
        Float,
        nullable=False,
        default=0.0,
    )

    rating_score: Mapped[float] = mapped_column(
        Float,
        nullable=False,
        default=0.0,
    )

    review_score: Mapped[float] = mapped_column(
        Float,
        nullable=False,
        default=0.0,
    )

    source_score: Mapped[float] = mapped_column(
        Float,
        nullable=False,
        default=0.0,
    )

    confidence: Mapped[float | None] = mapped_column(
        Float,
        nullable=True,
    )

    rank: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
    )

    explanation: Mapped[dict[str, object] | None] = mapped_column(
        JSON,
        nullable=True,
    )

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        default=utc_now,
        nullable=False,
    )

    session: Mapped["SearchSession"] = relationship(
        "SearchSession",
        back_populates="recommendations",
    )

    product: Mapped["Product"] = relationship(
        "Product",
        back_populates="recommendations",
    )